arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // In .NET 9, ZipArchiveEntry now respects the UTF-8 flag in the entry header.
        // Our legacy Java consumer reads filenames in Shift-JIS, so we must explicitly
        // encode entry names in Shift-JIS and avoid setting the UTF-8 flag.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift-JIS");

        using var stream = File.Create("data.zip");
        using var archive = new ZipArchive(stream, ZipArchiveMode.Create, leaveOpen: false, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

